// AI MCQ Maker. A student describes a topic (or pastes a fuller prompt), picks a
// difficulty and a question count (1-25), and gets a practice set generated by AI.
//
// Questions are requested in small batches (BATCH_SIZE per call) and stitched together
// here: a single call for 25 questions would outlast the provider timeout, and one
// failed batch should cost 5 questions, not the whole set. Whatever has been generated
// is kept if a later batch fails, so the student can start with what they have.
//
// Nothing is saved to the question bank or to progress/streaks — the set lives in this
// browser tab (sessionStorage, so a refresh or the app being backgrounded doesn't throw
// away a set that cost an AI call).
import { useEffect, useRef, useState } from 'react';
import { useQuery } from '@tanstack/react-query';
import { Check, ChevronRight, Minus, Plus, RotateCcw, Sparkles, X } from 'lucide-react';
import { aiMcqMakerApi, ApiRequestError, siteContentApi, type AiMcq, type AiMcqDifficulty } from '@/lib/api';
import { cn } from '@/lib/utils';
import { invalidatePracticeQueries } from '@/lib/query-client';
import { Badge, BrandSpinner, EmptyState, SectionHeader, difficultyTone } from '@/lib/shared';

const MAX_QUESTIONS = 25;
const MIN_QUESTIONS = 1;
const BATCH_SIZE = 5;
const COUNT_PRESETS = [5, 10, 15, 25];
const STORAGE_KEY = 'ai-mcq-maker-session-v1';

const DIFFICULTIES: Array<{ id: AiMcqDifficulty; label: string; hint: string }> = [
  { id: 'easy', label: 'Easy', hint: 'Core facts and definitions' },
  { id: 'moderate', label: 'Moderate', hint: 'Connecting concepts, textbook scenarios' },
  { id: 'hard', label: 'Hard', hint: 'Multi-step reasoning, fine distinctions' },
  { id: 'mixed', label: 'Mixed', hint: 'A bit of everything' },
];

const EXAMPLES = [
  'Cardiac cycle and heart sounds',
  'Management of diabetic ketoacidosis, clinical vignettes',
  'Brachial plexus lesions and their presentations',
  'Antibiotics: mechanisms of action and common side effects',
  'Acid–base disorders: interpreting blood gases',
];

type Phase = 'setup' | 'generating' | 'quiz' | 'results';

interface Settings { prompt: string; difficulty: AiMcqDifficulty; count: number }
interface Session {
  phase: Phase;
  settings: Settings;
  questions: AiMcq[];
  /** answers[i] = the option the student picked for question i, or undefined if not answered yet. */
  answers: Array<string | undefined>;
  index: number;
  /** True once this set has been recorded as a practice session, so it's only counted once. */
  saved?: boolean;
  /** ms timestamp when the student started answering — used for time spent. */
  startedAt?: number;
}

const DEFAULT_SETTINGS: Settings = { prompt: '', difficulty: 'mixed', count: 10 };

function loadSession(): Session | null {
  try {
    const raw = sessionStorage.getItem(STORAGE_KEY);
    if (!raw) return null;
    const s = JSON.parse(raw) as Session;
    // A tab that was mid-generation can't resume that request — fall back to whatever was finished.
    if (!s || !Array.isArray(s.questions) || !s.questions.length) return null;
    return { ...s, phase: s.phase === 'results' ? 'results' : 'quiz' };
  } catch { return null; }
}
function saveSession(s: Session | null) {
  try {
    if (s && s.questions.length && (s.phase === 'quiz' || s.phase === 'results')) sessionStorage.setItem(STORAGE_KEY, JSON.stringify(s));
    else sessionStorage.removeItem(STORAGE_KEY);
  } catch { /* storage can be unavailable (private mode / native webview) — the set just won't survive a refresh */ }
}

/** One line per option explaining why it is right or wrong. Renders nothing if the AI gave none. */
function OptionExplanations({ q, picked }: { q: AiMcq; picked?: string }) {
  const exps = q.optionExplanations ?? [];
  if (!exps.some((e) => e?.trim())) return null;
  return <div className="mt-3 space-y-1.5" data-testid="list-mcq-maker-option-explanations">
    <div className="text-[10px] font-extrabold uppercase tracking-wide text-muted-foreground">Why each option</div>
    {q.options.map((opt, oi) => {
      const text = exps[oi]?.trim();
      if (!text) return null;
      const isCorrect = opt === q.correctAnswer;
      const isPicked = picked === opt;
      return <div key={oi} className={cn('flex items-start gap-2 rounded-lg border p-2.5 text-xs leading-5', isCorrect ? 'border-emerald-500/40 bg-emerald-500/5' : isPicked ? 'border-red-500/40 bg-red-500/5' : 'border-border bg-background/60')} data-testid={`text-mcq-maker-option-explanation-${oi}`}>
        <span className={cn('mt-0.5 grid size-5 shrink-0 place-items-center rounded-full text-[10px] font-extrabold text-white', isCorrect ? 'bg-emerald-600' : isPicked ? 'bg-red-600' : 'bg-muted-foreground/60')}>{String.fromCharCode(65 + oi)}</span>
        <div><span className="font-bold">{opt}</span>{isCorrect ? <span className="font-bold text-emerald-700 dark:text-emerald-400"> · Correct</span> : isPicked ? <span className="font-bold text-red-600"> · Your answer</span> : null}<div className="text-muted-foreground">{text}</div></div>
      </div>;
    })}
  </div>;
}

const clampCount = (n: number) => Math.min(MAX_QUESTIONS, Math.max(MIN_QUESTIONS, Math.round(n) || MIN_QUESTIONS));

function AiMcqMaker() {
  const siteContentQ = useQuery({ queryKey: ['site-content'], queryFn: siteContentApi.get });
  const enabled = siteContentQ.data?.AI_MCQ_MAKER_ENABLED !== 'false';

  const restored = useRef(loadSession()).current;
  const [phase, setPhase] = useState<Phase>(restored?.phase ?? 'setup');
  const [settings, setSettings] = useState<Settings>(restored?.settings ?? DEFAULT_SETTINGS);
  const [questions, setQuestions] = useState<AiMcq[]>(restored?.questions ?? []);
  const [answers, setAnswers] = useState<Array<string | undefined>>(restored?.answers ?? []);
  const [index, setIndex] = useState(restored?.index ?? 0);
  const [saved, setSaved] = useState(restored?.saved ?? false);
  const startedAt = useRef(restored?.startedAt ?? Date.now());
  const [saveError, setSaveError] = useState(false);
  const [error, setError] = useState<string | null>(null);
  // Set when generation stopped early but some questions exist — offers "start with what we have".
  const [partial, setPartial] = useState(false);
  const cancelled = useRef(false);

  useEffect(() => { saveSession({ phase, settings, questions, answers, index, saved, startedAt: startedAt.current }); }, [phase, settings, questions, answers, index, saved]);
  useEffect(() => () => { cancelled.current = true; }, []);

  // Record the set as a practice session once the student reaches the results screen
  // (only the questions they actually answered count). Retries if the request failed.
  const savingRef = useRef(false);
  useEffect(() => {
    if (phase !== 'results' || saved || saveError || savingRef.current) return;
    const answered = answers.filter((a) => a !== undefined).length;
    if (!answered) return;
    const correct = questions.filter((q, i) => answers[i] === q.correctAnswer).length;
    savingRef.current = true;
    aiMcqMakerApi.saveSession({ answered, correct, durationSeconds: Math.round((Date.now() - startedAt.current) / 1000) })
      .then(() => { setSaved(true); setSaveError(false); invalidatePracticeQueries(); })
      .catch(() => setSaveError(true))
      .finally(() => { savingRef.current = false; });
  }, [phase, saved, saveError, answers, questions]);

  if (!siteContentQ.isLoading && !enabled) return <EmptyState icon={Sparkles} title="AI MCQ Maker is turned off" body="This feature isn't available right now — check back later." />;

  const begin = (qs: AiMcq[]) => {
    setQuestions(qs); setAnswers(qs.map(() => undefined)); setIndex(0); setPartial(false); setError(null); setSaved(false); setSaveError(false); startedAt.current = Date.now(); setPhase('quiz');
  };

  /** Asks for questions batch by batch until `target` are collected or a batch fails. `seed` = questions already kept. */
  const generate = async (s: Settings, seed: AiMcq[] = []) => {
    cancelled.current = false;
    setError(null); setPartial(false); setQuestions(seed); setPhase('generating');
    const got: AiMcq[] = [...seed];
    let emptyBatches = 0;
    while (got.length < s.count && !cancelled.current) {
      const want = Math.min(BATCH_SIZE, s.count - got.length);
      try {
        const { questions: batch } = await aiMcqMakerApi.generate({ prompt: s.prompt, difficulty: s.difficulty, count: want, avoid: got.map((q) => q.question).slice(-25) });
        // Drop repeats the model produced despite being told not to.
        const seen = new Set(got.map((q) => q.question.trim().toLowerCase()));
        const fresh = batch.filter((q) => !seen.has(q.question.trim().toLowerCase())).slice(0, s.count - got.length);
        got.push(...fresh);
        setQuestions([...got]);
        // A batch that adds nothing twice in a row means the model is stuck — stop rather than loop forever.
        emptyBatches = fresh.length ? 0 : emptyBatches + 1;
        if (emptyBatches >= 2) { setError("The AI couldn't come up with more distinct questions on this topic."); break; }
      } catch (err) {
        if (cancelled.current) return;
        setError(err instanceof ApiRequestError ? err.message : "Couldn't reach the AI right now. Check your connection and try again.");
        break;
      }
    }
    if (cancelled.current) return;
    if (got.length >= s.count) { begin(got.slice(0, s.count)); return; }
    // Fell short. Keep what we have so the student can use it or retry the rest.
    setQuestions(got);
    setPartial(got.length > 0);
    setPhase('setup');
  };

  const submit = () => {
    const prompt = settings.prompt.trim();
    if (prompt.length < 3) return;
    generate({ ...settings, prompt, count: clampCount(settings.count) });
  };
  const cancelGeneration = () => { cancelled.current = true; setPhase('setup'); setPartial(questions.length > 0); setError(null); };
  const reset = () => { cancelled.current = true; setSaved(false); setSaveError(false); setQuestions([]); setAnswers([]); setIndex(0); setPartial(false); setError(null); setPhase('setup'); };

  // ---------------------------------------------------------------- setup
  if (phase === 'setup') {
    const promptOk = settings.prompt.trim().length >= 3;
    return <div className="mx-auto max-w-3xl">
      <SectionHeader eyebrow="Study tools" title="AI MCQ Maker" description="Type any topic — or a fuller instruction like “management of DKA, clinical vignettes” — and get a practice set written for you." />

      {error && <div className="mb-4 rounded-xl border border-destructive/30 bg-destructive/5 p-3 text-xs text-destructive" data-testid="text-mcq-maker-error">
        {error}
        {partial && <div className="mt-1 text-muted-foreground">{questions.length} of {settings.count} questions were ready before it stopped.</div>}
      </div>}
      {partial && questions.length > 0 && <div className="mb-4 flex flex-wrap items-center gap-2 rounded-xl border border-primary/25 bg-primary/5 p-3 text-xs" data-testid="card-mcq-maker-partial">
        <span className="font-bold">{questions.length} question{questions.length === 1 ? '' : 's'} ready.</span>
        <button onClick={() => begin(questions)} className="rounded-lg bg-primary px-3 py-1.5 font-extrabold text-primary-foreground" data-testid="button-mcq-maker-start-partial">Start with these</button>
        <button onClick={() => generate({ ...settings, prompt: settings.prompt.trim() }, questions)} className="rounded-lg border border-border px-3 py-1.5 font-bold" data-testid="button-mcq-maker-retry-rest">Generate the rest</button>
      </div>}

      <div className="rounded-2xl border border-border bg-card p-4 sm:p-5">
        <label htmlFor="mcq-maker-prompt" className="text-[11px] font-extrabold uppercase tracking-wide text-muted-foreground">Topic or prompt</label>
        <textarea
          id="mcq-maker-prompt"
          value={settings.prompt}
          maxLength={500}
          onChange={(e) => setSettings({ ...settings, prompt: e.target.value })}
          placeholder="e.g. Brachial plexus lesions and their presentations"
          className="mt-1.5 min-h-28 w-full resize-none rounded-xl border border-border bg-background p-3 text-sm leading-6 outline-none focus:ring-2 focus:ring-primary/20"
          data-testid="textarea-mcq-maker-prompt"
        />
        <div className="mt-1 text-right text-[10px] text-muted-foreground">{settings.prompt.length}/500</div>
        <div className="mt-2 flex flex-wrap gap-2">
          {EXAMPLES.map((ex) => (
            <button key={ex} type="button" onClick={() => setSettings({ ...settings, prompt: ex })} className="rounded-full border border-border px-3 py-1.5 text-[11px] font-semibold text-muted-foreground hover:bg-muted hover:text-foreground" data-testid={`button-mcq-maker-example-${EXAMPLES.indexOf(ex)}`}>{ex}</button>
          ))}
        </div>

        <div className="mt-5 text-[11px] font-extrabold uppercase tracking-wide text-muted-foreground">Difficulty</div>
        <div className="mt-1.5 grid grid-cols-2 gap-2 sm:grid-cols-4" role="radiogroup" aria-label="Difficulty">
          {DIFFICULTIES.map((d) => (
            <button key={d.id} type="button" role="radio" aria-checked={settings.difficulty === d.id} title={d.hint} onClick={() => setSettings({ ...settings, difficulty: d.id })}
              className={cn('rounded-xl border px-3 py-2.5 text-xs font-extrabold transition-colors', settings.difficulty === d.id ? 'border-primary bg-primary/10 text-primary' : 'border-border text-muted-foreground hover:bg-muted hover:text-foreground')}
              data-testid={`button-mcq-maker-difficulty-${d.id}`}>{d.label}</button>
          ))}
        </div>
        <div className="mt-1.5 text-[11px] text-muted-foreground">{DIFFICULTIES.find((d) => d.id === settings.difficulty)?.hint}</div>

        <div className="mt-5 text-[11px] font-extrabold uppercase tracking-wide text-muted-foreground">Number of questions <span className="font-semibold normal-case tracking-normal">(max {MAX_QUESTIONS})</span></div>
        <div className="mt-1.5 flex flex-wrap items-center gap-3">
          <div className="inline-flex items-center rounded-xl border border-border" role="group" aria-label="Number of questions">
            <button type="button" aria-label="Fewer questions" disabled={settings.count <= MIN_QUESTIONS} onClick={() => setSettings({ ...settings, count: clampCount(settings.count - 1) })} className="grid size-10 place-items-center text-muted-foreground disabled:opacity-30" data-testid="button-mcq-maker-count-minus"><Minus size={15} /></button>
            <div className="w-12 text-center text-base font-extrabold tabular-nums" aria-live="polite" data-testid="text-mcq-maker-count">{settings.count}</div>
            <button type="button" aria-label="More questions" disabled={settings.count >= MAX_QUESTIONS} onClick={() => setSettings({ ...settings, count: clampCount(settings.count + 1) })} className="grid size-10 place-items-center text-muted-foreground disabled:opacity-30" data-testid="button-mcq-maker-count-plus"><Plus size={15} /></button>
          </div>
          <div className="flex flex-wrap gap-2">
            {COUNT_PRESETS.map((n) => (
              <button key={n} type="button" onClick={() => setSettings({ ...settings, count: n })}
                className={cn('rounded-full border px-3 py-1.5 text-[11px] font-extrabold', settings.count === n ? 'border-primary bg-primary/10 text-primary' : 'border-border text-muted-foreground hover:bg-muted hover:text-foreground')}
                data-testid={`button-mcq-maker-count-${n}`}>{n}</button>
            ))}
          </div>
        </div>
        {settings.count > BATCH_SIZE && <div className="mt-2 text-[11px] text-muted-foreground">Bigger sets are written in rounds of {BATCH_SIZE}, so they take a little longer.</div>}

        <button onClick={submit} disabled={!promptOk}
          className="mt-6 inline-flex w-full items-center justify-center gap-2 rounded-xl bg-primary px-5 py-3 text-xs font-extrabold text-primary-foreground transition-transform hover:-translate-y-0.5 disabled:opacity-50 sm:w-auto"
          data-testid="button-mcq-maker-generate"><Sparkles size={14} /> Generate {settings.count} question{settings.count === 1 ? '' : 's'}</button>
        <p className="mt-3 text-[10px] leading-4 text-muted-foreground">AI-written questions can contain mistakes — double-check important facts against your textbooks. Your answers count toward your progress, streak and leaderboard, but the questions themselves aren't kept in the question bank.</p>
      </div>
    </div>;
  }

  // ----------------------------------------------------------- generating
  if (phase === 'generating') {
    const pct = Math.round((questions.length / settings.count) * 100);
    return <div className="mx-auto max-w-xl">
      <div className="grid min-h-[320px] place-items-center rounded-2xl border border-border bg-card p-8 text-center" role="status" aria-live="polite">
        <div className="w-full">
          <BrandSpinner size={44} className="mx-auto text-primary" />
          <h3 className="mt-5 text-[15px] font-extrabold">Writing your questions…</h3>
          <p className="mx-auto mt-1.5 max-w-xs text-xs leading-5 text-muted-foreground">{questions.length} of {settings.count} ready. Keep this screen open.</p>
          <div className="mx-auto mt-4 h-2 max-w-xs overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all duration-500" style={{ width: `${Math.max(4, pct)}%` }} /></div>
          <button onClick={cancelGeneration} className="mt-6 rounded-lg border border-border px-4 py-2 text-xs font-bold text-muted-foreground hover:bg-muted" data-testid="button-mcq-maker-cancel">Cancel</button>
        </div>
      </div>
    </div>;
  }

  const answeredCount = answers.filter((a) => a !== undefined).length;
  const correctCount = questions.filter((q, i) => answers[i] === q.correctAnswer).length;

  // -------------------------------------------------------------- results
  if (phase === 'results') {
    const pct = questions.length ? Math.round((correctCount / questions.length) * 100) : 0;
    const missed = questions.map((q, i) => ({ q, i })).filter(({ q, i }) => answers[i] !== q.correctAnswer);
    return <div className="mx-auto max-w-3xl">
      <SectionHeader eyebrow="AI MCQ Maker" title="Your results" description={settings.prompt} />
      <div className="rounded-2xl border border-border bg-card p-5 text-center" data-testid="card-mcq-maker-score">
        <div className="text-4xl font-extrabold tabular-nums">{pct}%</div>
        <div className="mt-1 text-xs text-muted-foreground">{correctCount} correct out of {questions.length}{answeredCount < questions.length ? ` (${questions.length - answeredCount} unanswered)` : ''}</div>
        {answeredCount > 0 && <div className={cn('mt-2 text-[11px]', saveError ? 'text-destructive' : 'text-muted-foreground')} data-testid="text-mcq-maker-saved">
          {saved ? 'Saved to your progress, streak and leaderboard.' : saveError ? <>Couldn't save this session. <button className="font-bold underline" onClick={() => setSaveError(false)}>Try again</button></> : 'Saving to your progress…'}
        </div>}
        <div className="mt-4 flex flex-wrap justify-center gap-2">
          {missed.length > 0 && <button onClick={() => { const qs = missed.map(({ q }) => q); begin(qs); }} className="inline-flex items-center gap-1.5 rounded-xl bg-primary px-4 py-2.5 text-xs font-extrabold text-primary-foreground" data-testid="button-mcq-maker-retry-missed"><RotateCcw size={13} /> Retry {missed.length} missed</button>}
          <button onClick={() => generate({ ...settings }, [])} className="inline-flex items-center gap-1.5 rounded-xl border border-border px-4 py-2.5 text-xs font-extrabold" data-testid="button-mcq-maker-same-topic"><Sparkles size={13} /> New set, same topic</button>
          <button onClick={reset} className="rounded-xl border border-border px-4 py-2.5 text-xs font-extrabold" data-testid="button-mcq-maker-new-topic">Change topic</button>
        </div>
      </div>
      <h3 className="mb-2 mt-6 text-sm font-extrabold">Review</h3>
      <div className="space-y-3">
        {questions.map((q, i) => {
          const picked = answers[i];
          const ok = picked === q.correctAnswer;
          return <details key={i} className="group rounded-xl border border-border bg-card" data-testid={`review-mcq-${i}`}>
            <summary className="flex cursor-pointer list-none items-start gap-3 p-3.5">
              <span className={cn('mt-0.5 grid size-5 shrink-0 place-items-center rounded-full text-white', ok ? 'bg-emerald-600' : picked === undefined ? 'bg-muted-foreground/60' : 'bg-red-600')}>{ok ? <Check size={12} /> : <X size={12} />}</span>
              <span className="text-xs font-semibold leading-5">{i + 1}. {q.question}</span>
              <ChevronRight size={14} className="ml-auto mt-1 shrink-0 text-muted-foreground transition-transform group-open:rotate-90" />
            </summary>
            <div className="space-y-1.5 border-t border-border p-3.5 text-xs leading-5">
              {picked !== undefined && !ok && <div><span className="font-bold text-red-600">Your answer:</span> {picked}</div>}
              {picked === undefined && <div className="text-muted-foreground">You didn't answer this one.</div>}
              <div><span className="font-bold text-emerald-700 dark:text-emerald-400">Correct answer:</span> {q.correctAnswer}</div>
              <p className="text-muted-foreground">{q.explanation}</p>
              <OptionExplanations q={q} picked={picked} />
            </div>
          </details>;
        })}
      </div>
    </div>;
  }

  // ----------------------------------------------------------------- quiz
  const q = questions[index];
  if (!q) { reset(); return null; }
  const picked = answers[index];
  const revealed = picked !== undefined;
  const isLast = index === questions.length - 1;
  const choose = (opt: string) => { if (revealed) return; setAnswers((prev) => { const next = [...prev]; next[index] = opt; return next; }); };

  return <div className="mx-auto max-w-3xl">
    <div className="mb-3 flex items-center justify-between gap-3">
      <div className="min-w-0">
        <div className="font-mono-app text-[10px] font-bold uppercase tracking-[.16em] text-primary">AI MCQ Maker</div>
        <div className="truncate text-xs text-muted-foreground">{settings.prompt}</div>
      </div>
      <button onClick={() => setPhase('results')} className="shrink-0 rounded-lg border border-border px-3 py-1.5 text-[11px] font-bold text-muted-foreground hover:bg-muted" data-testid="button-mcq-maker-finish-early">{answeredCount === 0 ? 'Exit' : 'Finish'}</button>
    </div>
    <div className="mb-4 flex items-center gap-3">
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-muted"><div className="h-full rounded-full bg-primary transition-all" style={{ width: `${((index + (revealed ? 1 : 0)) / questions.length) * 100}%` }} /></div>
      <div className="text-[11px] font-bold tabular-nums text-muted-foreground" data-testid="text-mcq-maker-progress">{index + 1} / {questions.length}</div>
    </div>

    <div className="rounded-2xl border border-border bg-card p-4 sm:p-5">
      <div className="mb-3 flex items-center gap-2"><Badge tone={difficultyTone(q.difficulty)}>{q.difficulty}</Badge></div>
      <h3 className="text-[15px] font-bold leading-6" data-testid="text-mcq-maker-question">{q.question}</h3>
      <div className="mt-4 space-y-2.5" role="radiogroup" aria-label="Answer options">
        {q.options.map((opt, i) => {
          const isCorrect = opt === q.correctAnswer;
          const isPicked = picked === opt;
          return <button key={opt} type="button" role="radio" aria-checked={isPicked} disabled={revealed} onClick={() => choose(opt)}
            className={cn('flex w-full items-start gap-3 rounded-xl border p-3 text-left text-[13px] leading-5 transition-colors',
              !revealed && 'border-border hover:border-primary/40 hover:bg-muted/60',
              revealed && isCorrect && 'border-emerald-500/60 bg-emerald-500/10',
              revealed && isPicked && !isCorrect && 'border-red-500/60 bg-red-500/10',
              revealed && !isCorrect && !isPicked && 'border-border opacity-60')}
            data-testid={`button-mcq-maker-option-${i}`}>
            <span className={cn('grid size-6 shrink-0 place-items-center rounded-full border text-[11px] font-extrabold', revealed && isCorrect ? 'border-emerald-600 bg-emerald-600 text-white' : revealed && isPicked ? 'border-red-600 bg-red-600 text-white' : 'border-border text-muted-foreground')}>{revealed && isCorrect ? <Check size={12} /> : revealed && isPicked ? <X size={12} /> : String.fromCharCode(65 + i)}</span>
            <span className="pt-0.5">{opt}</span>
          </button>;
        })}
      </div>

      {revealed && <div className="mt-4 rounded-xl bg-muted/60 p-3.5 text-xs leading-5" data-testid="text-mcq-maker-explanation">
        <div className={cn('mb-1 font-extrabold', picked === q.correctAnswer ? 'text-emerald-700 dark:text-emerald-400' : 'text-red-600')}>{picked === q.correctAnswer ? 'Correct' : 'Not quite'}</div>
        {q.explanation}
        <OptionExplanations q={q} picked={picked} />
      </div>}

      <div className="mt-5 flex items-center justify-between gap-3">
        <div className="text-[11px] text-muted-foreground tabular-nums">Score: {correctCount}/{answeredCount}</div>
        <button onClick={() => (isLast ? setPhase('results') : setIndex(index + 1))} disabled={!revealed}
          className="inline-flex items-center gap-1.5 rounded-xl bg-primary px-5 py-2.5 text-xs font-extrabold text-primary-foreground disabled:opacity-40" data-testid="button-mcq-maker-next">
          {isLast ? 'See results' : 'Next'} <ChevronRight size={13} />
        </button>
      </div>
    </div>
  </div>;
}

export default AiMcqMaker;
